INSERT INTO cms_pages (title, slug, excerpt, content, meta_title, meta_description, status, show_in_footer, created_at, updated_at) VALUES
('About FixitNow', 'about', 'A service desk built to make appliance repair simple, transparent, and reliable.', '<h2>Service that respects your time</h2><p>FixitNow started with a simple frustration: booking an appliance repair should not mean endless calls, uncertain arrival windows, and paper receipts that disappear. We built a single platform where customers can book, track, and review every service visit — and where technicians have everything they need to do great work.</p><p>Today our network of vetted technicians handles air conditioners, refrigerators, laundry machines, cooking appliances, and more across Oriental Mindoro. Every job is backed by a written service report and a transparent cost estimate approved before work begins.</p><h3>What we stand for</h3><ul><li><strong>Clarity.</strong> Real ticket tracking, clear estimates, and no surprise charges.</li><li><strong>Craftsmanship.</strong> Certified technicians who explain the diagnosis in plain language.</li><li><strong>Accountability.</strong> Every visit ends with a service report and a chance to rate the work.</li></ul><p>Whether it is a squeaky dryer or a full aircon installation, FixitNow keeps the process organized from request to review.</p>', 'About FixitNow', 'Learn how FixitNow organizes appliance repair and maintenance from booking to service report.', 'published', 1, DATE_SUB(NOW(), INTERVAL 250 DAY), DATE_SUB(NOW(), INTERVAL 20 DAY)),
('Terms of Service', 'terms', 'The rules that keep FixitNow bookings fair and clear for everyone.', '<h2>1. Booking and confirmation</h2><p>Submitting a request does not automatically confirm an appointment. A FixitNow coordinator assigns a qualified technician and publishes a schedule, which you can view in your customer dashboard. You may cancel requests that have not yet started.</p><h2>2. Estimates and approvals</h2><p>Estimated costs are based on the selected service category and the information you provide. Final costs may change if the on-site diagnosis reveals additional faults. Technicians will explain any change before proceeding.</p><h2>3. Service reports</h2><p>Completed jobs include a service report describing the diagnosis, work performed, parts used, and recommendations. Please review the report in your dashboard.</p><h2>4. Feedback</h2><p>After a job is completed you may submit a rating and comment. Feedback helps us maintain service quality and may be featured on our website without personal contact details.</p><h2>5. Liability</h2><p>FixitNow technicians follow standard safety procedures. Customers are responsible for providing accurate appliance details, safe access, and disclosure of known hazards. Warranty on parts follows the manufacturer or supplier terms.</p>', 'Terms of Service', 'Read the FixitNow terms covering bookings, estimates, service reports, and feedback.', 'published', 1, DATE_SUB(NOW(), INTERVAL 240 DAY), DATE_SUB(NOW(), INTERVAL 60 DAY)),
('Privacy Policy', 'privacy', 'How we collect, use, and protect the information you share with FixitNow.', '<h2>Information we collect</h2><p>When you create an account or submit a service request we collect your name, email address, phone number, service address, appliance details, and request history. Technicians see only the information required to complete the assigned job.</p><h2>How we use information</h2><p>We use your information to schedule visits, assign technicians, generate service reports, provide support, and improve the platform. We do not sell personal data.</p><h2>Data retention</h2><p>Service records are retained for warranty, accounting, and quality assurance purposes. You may request account deactivation by contacting our support team.</p><h2>Security</h2><p>Passwords are hashed, access is role-based, and administrative actions are logged. Report any privacy concern to our support address and we will respond promptly.</p>', 'Privacy Policy', 'How FixitNow collects, uses, and protects customer and technician information.', 'published', 1, DATE_SUB(NOW(), INTERVAL 240 DAY), DATE_SUB(NOW(), INTERVAL 70 DAY)),
('Service Guide', 'service-guide', 'How to prepare for a technician visit and what to expect.', '<h2>Before the visit</h2><ol><li>Clear the area around the appliance so the technician can work safely.</li><li>Have the brand, model, and serial number ready if possible.</li><li>Note any error codes or unusual sounds you have observed.</li><li>Secure pets and inform us of any access restrictions.</li></ol><h2>During the visit</h2><p>Your technician will confirm the diagnosis and estimate before starting billable work. Ask questions at any point — our team is trained to explain the issue in plain language.</p><h2>After the visit</h2><p>Review the service report in your dashboard, keep the receipt for warranty purposes, and leave feedback so we can keep improving. If the issue returns within the warranty window, open a new request and reference the original ticket number.</p>', 'FixitNow Service Guide', 'Prepare for your appliance repair visit with this simple FixitNow checklist.', 'published', 0, DATE_SUB(NOW(), INTERVAL 200 DAY), DATE_SUB(NOW(), INTERVAL 40 DAY)),
('Careers', 'careers', 'We are always looking for careful, curious technicians.', '<h2>Join the FixitNow network</h2><p>We work with technicians who take pride in diagnostics, communication, and cleanup. If you have experience with major appliances and want a steady stream of scheduled work with clear job details, send us a message through the contact page and mention your specialty.</p><p>This page is still a draft and is not visible on the public site.</p>', 'Careers at FixitNow', 'Technician opportunities with the FixitNow appliance service network.', 'draft', 0, DATE_SUB(NOW(), INTERVAL 30 DAY), DATE_SUB(NOW(), INTERVAL 5 DAY));
